[
  {
    "incident": {
      "component": "batch-02:/data",
      "category": "Storage/Filesystem",
      "status": "firing",
      "summary": "Filesystem /data on batch-02 is 97% full despite du reporting lower usage, indicating deleted files are still held open by processes."
    },
    "assessment": {
      "urgency": "critical",
      "rationale": "The filesystem is at 97% capacity with a growth rate of 500MiB/h, meaning exhaustion will occur in approximately 12 hours, potentially causing application failure."
    },
    "facts": [
      "Alert: NodeFilesystemAlmostOutOfSpace on batch-02:9100",
      "Mountpoint: /data",
      "Filesystem type: xfs",
      "Filesystem size: 200GiB",
      "Available space: 6GiB",
      "Growth rate: 500MiB/h",
      "df -h shows 97% used",
      "du -sh /data shows ~120GB used",
      "A 70GB log file was deleted via 'rm' yesterday"
    ],
    "missing_context": [
      {
        "item": "List of open deleted files",
        "why": "To identify which process is holding the 70GB file open",
        "how_to_check": "lsof +L1 | grep /data"
      },
      {
        "item": "Current process list",
        "why": "To see if any batch jobs or logging agents are malfunctioning",
        "how_to_check": "ps auxf"
      }
    ],
    "immediate_actions": [
      {
        "action": "Identify and restart the process holding the deleted file",
        "purpose": "To release the disk space held by the unlinked file",
        "conditions": "If lsof shows a process holding a deleted file on /data",
        "expected_effect": "Disk space is immediately reclaimed by the OS",
        "risks": "Restarting the process might interrupt a running batch job",
        "requires_approval": true,
        "verify": "Run 'df -h /data' to see if available space increases",
        "rule_ids": [
          "RECLAIM_DELETED_SPACE"
        ]
      }
    ],
    "investigation_steps": [
      {
        "step": "Check for unlinked files held by processes",
        "hypothesis": "The 'rm' command deleted a file that was still being written to by an active process, preventing the space from being reclaimed.",
        "how_to_check": "lsof /data | grep '(deleted)'"
      },
      {
        "step": "Check inode usage",
        "hypothesis": "The filesystem might be running out of inodes rather than blocks (though unlikely given the metrics)",
        "how_to_check": "df -i /data"
      }
    ],
    "root_cause_hypotheses": [
      "Process is holding a file descriptor to a deleted file (common with log rotation failures)",
      "Large log files are being deleted without a proper log rotation signal (SIGHUP) to the application"
    ],
    "dangerous_operations": [
      {
        "operation": "Killing critical batch processes",
        "why_dangerous": "May lead to data corruption or incomplete batch jobs",
        "rule_id": "PROC_KILL_RISK"
      }
    ],
    "applied_expert_rules": [
      "RECLAIM_DELETED_SPACE"
    ],
    "incident_update": "🚨 *Critical Alert: batch-02 /data filesystem at 97% capacity.* Discrepancy between `df` and `du` suggests a deleted file is still held open by a process. Investigating via `lsof` to identify the culprit. Growth rate is 500MiB/h."
  }
]
